            Q('e2', L('Perché usare lo stesso modello di embedding per documenti e domande?', 'Why use the same embedding model for documents and questions?'), [L('I vettori di modelli diversi non sono confrontabili', 'Vectors from different models are not comparable'), L('Perché Ollama ne carica solo uno', 'Because Ollama loads only one'), L('Per risparmiare spazio su disco', 'To save disk space'), L('Non serve: qualsiasi modello va bene', 'No need: any model will do')], 0, L('Spazi diversi, distanze senza senso.', 'Different spaces, meaningless distances.')),
            Q('e3', L('Che cosa ottieni con chat, embedding e database tutti locali?', 'What do you get with chat, embeddings and database all local?'), [L('Un RAG più veloce del cloud in ogni caso', 'A RAG faster than the cloud in every case'), L('Un RAG completamente offline, senza dati in uscita', 'A fully offline RAG, with no data leaving'), L('Un modello riaddestrato sui tuoi documenti', 'A model retrained on your documents'), L('Un RAG che non ha bisogno di documenti', 'A RAG that needs no documents')], 1, L('Ottimo per documenti riservati.', 'Great for confidential documents.')),
